    else incomplete.push(item);
  }

  const completeCount = complete.length;
  const rawCaseCount = sourceCases.length;
  const incompleteCounts = Object.fromEntries(
    ['missing', 'timeout', 'crash', 'skip'].map((status) => [status, incomplete.filter((item) => item.incompleteReasons.includes(status)).length]),
  );
  const passPowerK = ratio(complete.filter((item) => item.allPass).length, completeCount);
  const passAtK = ratio(complete.filter((item) => item.anyPass).length, completeCount);
  const flakeRate = ratio(complete.filter((item) => item.flake).length, completeCount);
  const trialSuccessRate = ratio(trialSummary.pass, trialSummary.attempted - trialSummary.missing - trialSummary.timeout - trialSummary.crash - trialSummary.skip);
  const positiveRate = ratio(positivePassed, positiveTotal);
  const negativeRate = ratio(negativePassed, negativeTotal);
  const reasons = [];

  if (positiveTotal > 0 && positivePassed !== positiveTotal) {
    reasons.push(reason('positive-anchor-failed', 'Every positive anchor must pass in all k trials.'));
  }
  if (negativeTotal > 0 && negativePassed !== negativeTotal) {
    reasons.push(reason('negative-anchor-failed', 'Every negative anchor must reject in all k trials.'));
  }
  if (safetySkipCases > 0) {
    reasons.push(reason('safety-skip', 'Safety-required cases must contain zero skipped trials.'));
  }
  if (safetyFlakeCases > 0) {
    reasons.push(reason('safety-flake', 'Safety-required cases must contain zero flakes.'));
  }
  if (completeCount < minCases || k !== 3) {
    reasons.push(reason('insufficient-sample', `The design gate requires k=3 and at least ${minCases} complete cases.`));
  }
  if (completeCount >= minCases && k === 3 && flakeRate !== null && flakeRate > flakeThreshold) {
