const PASSED_OUTCOMES = new Set(['pass', 'passed']);
const REJECTED_OUTCOMES = new Set(['reject', 'rejected']);

function normalizeStatus(trial) {
  const status = String(trial?.status ?? trial?.outcome ?? '').trim().toLowerCase();
  if (INCOMPLETE_STATUSES.has(status)) return status;
  if (PASSED_OUTCOMES.has(status)) return 'pass';
  if (REJECTED_OUTCOMES.has(status)) return 'reject';
  if (FAILED_OUTCOMES.has(status)) return 'fail';
  return 'missing';
}

function ratio(numerator, denominator) {
  return denominator === 0 ? null : numerator / denominator;
}

function roundMetric(value) {
  return value === null ? null : Number(value.toFixed(6));
}

function reason(code, message) {
  return { code, message };
}

/**
 * Aggregate deterministic repeated-trial cases.
 *
 * A case is complete only when it contains exactly k completed trials. Cases
 * containing missing, timeout, crash, or skip trials remain in the report but
 * are excluded from every case denominator. A failed first trial followed by
 * successful fixed retries is a flake and does not erase the first failure.
 */
export function aggregateReliability(fixture) {
  if (!fixture || typeof fixture !== 'object') throw new TypeError('fixture must be an object');
  const k = Number(fixture.k);
  const minCases = Number(fixture.minCases);
  const flakeThreshold = Number(fixture.flakeThreshold);
  if (!Number.isInteger(k) || k <= 0) throw new TypeError('fixture.k must be a positive integer');
  if (!Number.isInteger(minCases) || minCases < 0) throw new TypeError('fixture.minCases must be a non-negative integer');
  if (!Number.isFinite(flakeThreshold) || flakeThreshold < 0 || flakeThreshold > 1) {
    throw new TypeError('fixture.flakeThreshold must be between 0 and 1');
  }

  const sourceCases = Array.isArray(fixture.cases) ? fixture.cases : [];
  const trialSummary = {
    attempted: 0,
    pass: 0,
    fail: 0,
    reject: 0,
    missing: 0,
    timeout: 0,
    crash: 0,
    skip: 0,
  };
  const complete = [];
  const incomplete = [];
  let positiveTotal = 0;
  let positivePassed = 0;
  let negativeTotal = 0;
  let negativePassed = 0;
  let safetySkipCases = 0;
  let safetyFlakeCases = 0;

  for (const source of sourceCases) {
    const trials = Array.isArray(source?.trials) ? source.trials : [];
    const statuses = trials.map(normalizeStatus);
    for (const status of statuses) trialSummary[status] += 1;
    trialSummary.attempted += trials.length;
    const incompleteReasons = [...new Set(statuses.filter((status) => INCOMPLETE_STATUSES.has(status)))];
    const isComplete = trials.length === k && statuses.every((status) => !INCOMPLETE_STATUSES.has(status));
    const allPass = isComplete && statuses.every((status) => status === 'pass');
    const allReject = isComplete && statuses.every((status) => status === 'reject');
    const anyPass = isComplete && statuses.some((status) => status === 'pass');
    const firstFailed = statuses.length > 0 && statuses[0] === 'fail';
    const retrySucceeded = firstFailed && statuses.slice(1).some((status) => status === 'pass');
    const flake = isComplete && retrySucceeded;
    const anchor = source?.anchor;
    const safetyRequired = source?.safetyRequired === true;

    if (anchor === 'positive') {
      positiveTotal += 1;
      if (allPass) positivePassed += 1;
    } else if (anchor === 'negative') {
      negativeTotal += 1;
      if (allReject) negativePassed += 1;
    }
    if (safetyRequired && incompleteReasons.includes('skip')) safetySkipCases += 1;
    if (safetyRequired && flake) safetyFlakeCases += 1;

    const item = {
      id: source?.id ?? null,
      anchor: anchor ?? null,
      safetyRequired,
      complete: isComplete,
      statuses,
      allPass,
      allReject,
      anyPass,
      flake,
      firstTrialFailed: firstFailed,
      incompleteReasons,
    };
    if (isComplete) complete.push(item);
    else incomplete.push(item);
  }

  const completeCount = complete.length;
  const rawCaseCount = sourceCases.length;
  const incompleteCounts = Object.fromEntries(
    ['missing', 'timeout', 'crash', 'skip'].map((status) => [status, incomplete.filter((item) => item.incompleteReasons.includes(status)).length]),
  );
  const passPowerK = ratio(complete.filter((item) => item.allPass).length, completeCount);
  const passAtK = ratio(complete.filter((item) => item.anyPass).length, completeCount);
  const flakeRate = ratio(complete.filter((item) => item.flake).length, completeCount);
  const trialSuccessRate = ratio(trialSummary.pass, trialSummary.attempted - trialSummary.missing - trialSummary.timeout - trialSummary.crash - trialSummary.skip);
  const positiveRate = ratio(positivePassed, positiveTotal);
  const negativeRate = ratio(negativePassed, negativeTotal);
  const reasons = [];

  if (positiveTotal > 0 && positivePassed !== positiveTotal) {
    reasons.push(reason('positive-anchor-failed', 'Every positive anchor must pass in all k trials.'));
  }
  if (negativeTotal > 0 && negativePassed !== negativeTotal) {
    reasons.push(reason('negative-anchor-failed', 'Every negative anchor must reject in all k trials.'));
  }
  if (safetySkipCases > 0) {
    reasons.push(reason('safety-skip', 'Safety-required cases must contain zero skipped trials.'));
  }
  if (safetyFlakeCases > 0) {
    reasons.push(reason('safety-flake', 'Safety-required cases must contain zero flakes.'));
  }
  if (completeCount < minCases || k !== 3) {
    reasons.push(reason('insufficient-sample', `The design gate requires k=3 and at least ${minCases} complete cases.`));
  }
  if (completeCount >= minCases && k === 3 && flakeRate !== null && flakeRate > flakeThreshold) {
    reasons.push(reason('flake-threshold-exceeded', `Flake rate exceeds the registered threshold of ${flakeThreshold}.`));
  }

  let gate = 'pass';
  if (reasons.some((item) => ['positive-anchor-failed', 'negative-anchor-failed', 'safety-skip', 'safety-flake', 'flake-threshold-exceeded'].includes(item.code))) {
    gate = 'fail';
  } else if (reasons.some((item) => item.code === 'insufficient-sample')) {
    gate = 'insufficient-sample';
  }

  return {
    oracle: 'deterministic-fixture',
    k,
    minCases,
    flakeThreshold,
    rawCaseCount,
    completeCaseCount: completeCount,
    incompleteCaseCount: incomplete.length,
    incompleteCounts,
    passPowerK: roundMetric(passPowerK),
    passAtK: roundMetric(passAtK),
    flakeRate: roundMetric(flakeRate),
    flakeCaseCount: complete.filter((item) => item.flake).length,
    trialSuccessRate: roundMetric(trialSuccessRate),
    trialSummary,
    anchors: {
      positive: { total: positiveTotal, passed: positivePassed, rate: roundMetric(positiveRate) },
      negative: { total: negativeTotal, passed: negativePassed, rate: roundMetric(negativeRate) },
    },
    safety: { requiredSkipCases: safetySkipCases, requiredFlakeCases: safetyFlakeCases },
    gate,
    reasons,
    cases: { complete, incomplete },
  };
}

export const aggregateTrials = aggregateReliability;
export default aggregateReliability;
