    negative: { total: number; passed: number; rate: number | null };
  };
  safety: { requiredSkipCases: number; requiredFlakeCases: number };
  gate: 'pass' | 'fail' | 'insufficient-sample';
  reasons: Array<{ code: string; message: string }>;
