/**
 * Aggregate deterministic repeated-trial cases.
 *
 * A case is complete only when it contains exactly k completed trials. Cases
 * containing missing, timeout, crash, or skip trials remain in the report but
 * are excluded from every case denominator. A failed first trial followed by
 * successful fixed retries is a flake and does not erase the first failure.
 */
export function aggregateReliability(fixture) {
  if (!fixture || typeof fixture !== 'object') throw new TypeError('fixture must be an object');
  const k = Number(fixture.k);
  const minCases = Number(fixture.minCases);
  const flakeThreshold = Number(fixture.flakeThreshold);
  if (!Number.isInteger(k) || k <= 0) throw new TypeError('fixture.k must be a positive integer');
  if (!Number.isInteger(minCases) || minCases < 0) throw new TypeError('fixture.minCases must be a non-negative integer');
  if (!Number.isFinite(flakeThreshold) || flakeThreshold < 0 || flakeThreshold > 1) {
    throw new TypeError('fixture.flakeThreshold must be between 0 and 1');
  }

  const sourceCases = Array.isArray(fixture.cases) ? fixture.cases : [];
  const trialSummary = {
    attempted: 0,
    pass: 0,
    fail: 0,
    reject: 0,
    missing: 0,
    timeout: 0,
    crash: 0,
    skip: 0,
  };
  const complete = [];
  const incomplete = [];
  let positiveTotal = 0;
  let positivePassed = 0;
  let negativeTotal = 0;
  let negativePassed = 0;
  let safetySkipCases = 0;
  let safetyFlakeCases = 0;

  for (const source of sourceCases) {
    const trials = Array.isArray(source?.trials) ? source.trials : [];
    const statuses = trials.map(normalizeStatus);
    for (const status of statuses) trialSummary[status] += 1;
    trialSummary.attempted += trials.length;
    const incompleteReasons = [...new Set(statuses.filter((status) => INCOMPLETE_STATUSES.has(status)))];
    const isComplete = trials.length === k && statuses.every((status) => !INCOMPLETE_STATUSES.has(status));
    const allPass = isComplete && statuses.every((status) => status === 'pass');
    const allReject = isComplete && statuses.every((status) => status === 'reject');
    const anyPass = isComplete && statuses.some((status) => status === 'pass');
    const firstFailed = statuses.length > 0 && statuses[0] === 'fail';
    const retrySucceeded = firstFailed && statuses.slice(1).some((status) => status === 'pass');
    const flake = isComplete && retrySucceeded;
    const anchor = source?.anchor;
    const safetyRequired = source?.safetyRequired === true;

    if (anchor === 'positive') {
      positiveTotal += 1;
      if (allPass) positivePassed += 1;
    } else if (anchor === 'negative') {
      negativeTotal += 1;
      if (allReject) negativePassed += 1;
    }
    if (safetyRequired && incompleteReasons.includes('skip')) safetySkipCases += 1;
    if (safetyRequired && flake) safetyFlakeCases += 1;

